  }
]
After vectors.push the documentVectors is: [
  {
    docId: 'a894474d-b3f8-4d4c-bcd5-d5bb22c18a18',
    vectorId: 'af19b5fe-8830-4303-9a42-212deb5493a0'
  },
  {
